loads = [38, 39, 41, 44, 47, 52]   # MW in each of six 45-minute event windows
firm = 46                          # MW the grid can serve during the event
blocks = ['A', 'B', 'C', 'D', 'E', 'F']
shed_mw = 9
unserved = {b: 0.0 for b in blocks}
for w, load in enumerate(loads):
    deficit = load - firm
    if deficit > 0:
        nblocks = -(-deficit // shed_mw)   # blocks to drop this window
        for k in range(nblocks):
            b = blocks[(w + k) % len(blocks)]
            unserved[b] += shed_mw * 0.75  # MWh over the 45-minute window
for b in blocks:
    print(b, round(unserved[b], 2))
print('total unserved MWh:', round(sum(unserved.values()), 2))
